import React from 'react';

const Dashboard = () => {
  const agentsData = [
    { id: 1, name: 'Agent A', status: 'Online' },
    { id: 2, name: 'Agent B', status: 'Offline' },
    { id: 3, name: 'Agent C', status: 'Pending' },
  ];

  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', padding: '20px' }}>
      <h1>Agents Dashboard</h1>
      <table border="1" style={{ width: '80%', margin: '20px auto' }}>
        <thead>
          <tr>
            <th>ID</th>
            <th>Name</th>
            <th>Status</th>
          </tr>
        </thead>
        <tbody>
          {agentsData.map(agent => (
            <tr key={agent.id}>
              <td>{agent.id}</td>
              <td>{agent.name}</td>
              <td style={{ color: agent.status === 'Online' ? 'green' : agent.status === 'Offline' ? 'red' : 'orange' }}>{agent.status}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default Dashboard;

