/* Add premium styling */
body {
    background-color: #1e1e2f;
    color: #d4d4d4;
    font-family: 'Fira Code', monospace;
}

.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 2rem;
}

.header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 2rem;
}

.logo {
    font-size: 2.5rem;
    color: #61dafb;
}

.navbar {
    display: flex;
    gap: 1rem;
}

.nav-item {
    padding: 0.5rem 1rem;
    background-color: #333;
    border-radius: 4px;
    cursor: pointer;
    transition: background-color 0.3s ease;
}

.nav-item:hover {
    background-color: #555;
}

.code-editor {
    background-color: #282c34;
    color: #d4d4d4;
    border-radius: 4px;
    padding: 1rem;
    font-size: 0.9rem;
    line-height: 1.6;
    overflow-y: auto;
}

.code-editor:focus {
    outline: none;
    box-shadow: 0 0 5px #61dafb;
}

.button {
    background-color: #61dafb;
    color: #282c34;
    border: none;
    padding: 0.75rem 1.5rem;
    font-size: 0.9rem;
    cursor: pointer;
    border-radius: 4px;
    transition: background-color 0.3s ease;
}

.button:hover {
    background-color: #4caf50;
}

import React, { useState } from 'react';
import './PremiumCockpit.css';

const PremiumCockpit = () => {
    const [code, setCode] = useState('');
    const [output, setOutput] = useState('');

    const runCode = () => {
        try {
            const result = eval(code);
            setOutput(result);
        } catch (error) {
            setOutput(error.message);
        }
    };

    return (
        <div className="container">
            <header className="header">
                <div className="logo">Premium Coding Cockpit</div>
                <nav className="navbar">
                    <div className="nav-item">File Explorer</div>
                    <div className="nav-item">Settings</div>
                </nav>
            </header>
            <div className="code-editor" contentEditable="true" onInput={(e) => setCode(e.target.innerText)}></div>
            <button className="button" onClick={runCode}>Run Code</button>
            <pre>{output}</pre>
        </div>
    );
};

export default PremiumCockpit;

